Here is the root cause:
The bug was caused by the relocation of the I/O priority setting logic to a lower level in the block I/O submission process, specifically in the `blk_mq_submit_bio()` function. This change led to the omission of I/O priority initialization for block drivers that implement their own `submit_bio()` functions, such as Device Mapper (DM) and Multiple Device (MD), resulting in incorrect or uninitialized I/O priorities during bio submissions.

Here is the patch:
 #include "blk-mq-sched.h"
 #include "blk-rq-qos.h"
-#include "blk-ioprio.h"

 static DEFINE_PER_CPU(struct llist_head, blk_cpu_done);

-static void bio_set_ioprio(struct bio *bio)
-{
-	/* Nobody set ioprio so far? Initialize it based on task's nice value */
-	if (IOPRIO_PRIO_CLASS(bio->bi_ioprio) == IOPRIO_CLASS_NONE)
-		bio->bi_ioprio = get_current_ioprio();
-	blkcg_set_ioprio(bio);
-}
-
 /**
  * blk_mq_submit_bio - Create and send a request to block device.
  */
 void blk_mq_submit_bio(struct bio *bio)
 {
 	struct request_queue *q = bdev_get_queue(bio->bi_bdev);
 	struct blk_plug *plug = blk_mq_plug(bio);
 	const int is_sync = op_is_sync(bio->bi_opf);
 	struct blk_mq_hw_ctx *hctx;
 	struct request *rq = NULL;
 	unsigned int nr_segs = 1;
 	blk_status_t ret;

 	bio = blk_queue_bounce(bio, q);
-	bio_set_ioprio(bio);

 	if (plug) {
 		rq = rq_list_peek(&plug->cached_rq);
 		if (rq && rq->q != q)
 			rq = NULL;
 	}
 	if (rq) {
 		if (unlikely(bio_may_exceed_limits(bio, &q->limits))) {
 			bio = __bio_split_to_limits(bio, &q->limits, &nr_segs);
 			if (!bio)
 				return;
 		}
 		if (!bio_integrity_prep(bio))
 			return;
 		if (blk_mq_attempt_bio_merge(q, bio, nr_segs))
 			return;
 		if (blk_mq_use_cached_rq(rq, plug, bio))
 			goto done;
 		percpu_ref_get(&q->q_usage_counter);
 	} else {
 		if (unlikely(bio_queue_enter(bio)))
 			return;
 		if (unlikely(bio_may_exceed_limits(bio, &q->limits))) {
 			bio = __bio_split_to_limits(bio, &q->limits, &nr_segs);
 			if (!bio)
 				goto fail;
 		}
 		if (!bio_integrity_prep(bio))
 			goto fail;
 	}

 	rq = blk_mq_get_new_requests(q, plug, bio, nr_segs);
 	if (unlikely(!rq)) {
 fail:
 		blk_queue_exit(q);
 		return;
 	}

 done:
 	trace_block_getrq(bio);

 	rq_qos_track(q, rq, bio);

 	blk_mq_bio_to_request(rq, bio, nr_segs);

 	ret = blk_crypto_rq_get_keyslot(rq);
 	if (ret != BLK_STS_OK) {
 		bio->bi_status = ret;
 		bio_endio(bio);
 		blk_mq_free_request(rq);
 		return;
 	}

 	if (op_is_flush(bio->bi_opf) && blk_insert_flush(rq))
 		return;

 	if (plug) {
 		blk_add_rq_to_plug(plug, rq);
 		return;
 	}

 	hctx = rq->mq_hctx;
 	if ((rq->rq_flags & RQF_USE_SCHED) ||
 	    (hctx->dispatch_busy && (q->nr_hw_queues == 1 || !is_sync))) {
 		blk_mq_insert_request(rq, 0);
 		blk_mq_run_hw_queue(hctx, true);
 	} else {
 		blk_mq_run_dispatch_ops(q, blk_mq_try_issue_directly(hctx, rq));
 	}
 }



